def handle(query, state):
    import shlex, re

    # Virtual filesystem lives in state
    vfs = state.get('files', {})

    def run_cmd(argv):
        """Simulate a tiny set of POSIX commands against the virtual filesystem."""
        if not argv:
            return ''
        cmd = argv[0]
        args = argv[1:]
        if cmd == 'git':
            # git status [repo_path]
            if len(args) >= 2 and args[0] == 'status':
                repo_path = args[1]
                # In real scenario, would check repo metadata; here just return status
                return f'On branch main\nYour branch is up to date with origin/main.\nnothing to commit, working tree clean\n'
            return 'git: invalid command\n'
        elif cmd == 'cat':
            out = ''
            for path in args:
                content = vfs.get(path)
                if content is None:
                    out += f'cat: {path}: No such file or directory\n'
                else:
                    out += content
                    if not content.endswith('\n'):
                        out += '\n'
            return out
        elif cmd == 'echo':
            return ' '.join(args) + '\n'
        elif cmd == 'ls':
            path = args[0] if args else '/'
            entries = [k for k in vfs if k.startswith(path)]
            return '\n'.join(entries) + '\n' if entries else 'ls: no entries\n'
        elif cmd == 'pwd':
            return '/var/git/webhooks\n'
        else:
            return f'{cmd}: command not found\n'

    def shell_exec(cmdline):
        """Split on ';' and run each segment in sequence, concatenating output.
        Does NOT support $() or backtick expansion."""
        output = ''
        for segment in cmdline.split(';'):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment)
            except ValueError:
                argv = segment.split()
            output += run_cmd(argv)
        return output

    repo = (query.get('repo') or [''])[0]
    if not repo:
        body = 'Usage: ?repo=<repo_path>\n'
        return 200, {'Content-Type': 'text/plain'}, body

    # The vulnerable call: repo path is passed unsanitised into the shell emulator
    # Real webhook would typically do: git -C <repo> status
    output = shell_exec('git status ' + repo)
    return 200, {'Content-Type': 'text/plain'}, output
